"""LearnGED · Ciencias · Lección 2.2 · De la tabla a la gráfica y de la gráfica al texto (EN/ES).
Fuente: clases_ciencias/leccion_2-2.html y el interactivo ciencias/interpreta_graficos (CientíGraf).
Las gráficas se dibujan en SVG con ciencia.grafica().
Uso: python3 tools/build_sci_2_2.py
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import ciencia as C
from ciencia import t

N = "2-2"


def titulo():
    return t("From the table to the graph, and from the graph to the text", "De la tabla a la gráfica y de la gráfica al texto")


def anc(en, es):
    return en if C.L == "en" else es


CO2 = [[1960, 317], [1970, 326], [1980, 339], [1990, 354], [2000, 369], [2010, 390], [2020, 414]]


def graf_co2():
    spec = {"tipo": "linea", "xEtq": t("Year", "Año"), "yEtq": t("CO₂ (ppm)", "CO₂ (ppm)"), "py": 20, "px": 10, "series": [{"nombre": "CO₂", "puntos": CO2}]}
    aria = t("Line graph titled Average carbon dioxide in the atmosphere, measured at the Mauna Loa Observatory in Hawaii. Horizontal axis: year, from 1960 to 2020. Vertical axis: concentration in parts per million, starting at 300, not at zero. Values: 1960, 317; 1970, 326; 1980, 339; 1990, 354; 2000, 369; 2010, 390; 2020, 414. The line rises the whole time, and faster and faster.",
             "Gráfica de líneas titulada Concentración media de dióxido de carbono en la atmósfera, medida en el observatorio de Mauna Loa, en Hawái. Eje horizontal: año, de 1960 a 2020. Eje vertical: concentración en partes por millón, que empieza en 300, no en cero. Valores: 1960, 317; 1970, 326; 1980, 339; 1990, 354; 2000, 369; 2010, 390; 2020, 414. La línea sube todo el tiempo, y cada vez más deprisa.")
    return (f'<p class="titulo-graf"><strong>{t("Average carbon dioxide (CO₂) in the atmosphere, Mauna Loa Observatory (Hawaii), 1960–2020", "Concentración media de dióxido de carbono (CO₂) en la atmósfera, observatorio de Mauna Loa (Hawái), 1960–2020")}</strong></p>'
            + C.grafica(spec, aria, y0=300, y1=420))


def barras_recorte():
    datos = [("A", 62), ("B", 64), ("C", 66), ("D", 68)]
    def una(y0, y1, x0, tit):
        ml, W, mt, Hh = x0 + 46, 190, 30, 170
        Y = lambda v: mt + Hh - (v - y0) / (y1 - y0) * Hh
        g = [f'<text x="{ml + W / 2}" y="18" text-anchor="middle" font-size="14" font-weight="700" fill="#1a2330">{tit}</text>']
        for v in ([0, 50, 100] if y0 == 0 else [60, 65, 70]):
            g.append(f'<line x1="{ml}" y1="{Y(v):.1f}" x2="{ml + W}" y2="{Y(v):.1f}" stroke="#e1e6ea"/><text x="{ml - 6}" y="{Y(v) + 5:.1f}" text-anchor="end" font-size="13" fill="#3d4753">{v}</text>')
        for i, (e, v) in enumerate(datos):
            x = ml + 12 + i * 45
            g.append(f'<rect x="{x}" y="{Y(v):.1f}" width="30" height="{Y(y0) - Y(v):.1f}" fill="#2a7f86"/><text x="{x + 15}" y="{mt + Hh + 18}" text-anchor="middle" font-size="13" fill="#3d4753">{e}</text>')
        g.append(f'<line x1="{ml}" y1="{mt}" x2="{ml}" y2="{mt + Hh}" stroke="#1a2330"/><line x1="{ml}" y1="{mt + Hh}" x2="{ml + W}" y2="{mt + Hh}" stroke="#1a2330"/>')
        return "".join(g)
    aria = t("Two bar graphs with the same four values: 62, 64, 66, and 68 percent germination for treatments A, B, C, and D. On the left, the vertical axis goes from 0 to 100 and the four bars look almost equal. On the right, the vertical axis is cut to go from 60 to 70, and bar D looks four times taller than bar A, even though the real difference is only 6 percentage points.",
             "Dos gráficas de barras con los mismos cuatro datos: 62, 64, 66 y 68 por ciento de germinación en los tratamientos A, B, C y D. A la izquierda, el eje vertical va de 0 a 100 y las cuatro barras se ven casi iguales. A la derecha, el eje vertical está recortado entre 60 y 70, y la barra D parece cuatro veces la barra A, aunque la diferencia real es de solo 6 puntos porcentuales.")
    return (f'<svg viewBox="0 0 560 240" role="img" aria-label="{aria}" style="width:100%;max-width:560px;height:auto;display:block;margin:12px auto;">'
            + una(0, 100, 0, t("Axis from 0", "Eje desde 0")) + una(60, 70, 280, t("Axis cut at 60", "Eje recortado en 60")) + "</svg>")


