# ---------------------------------------------------------------- práctica
def banco_representacion():
    T4 = [t("Multiple-line graph", "Gráfica de líneas múltiples"), t("Double bar graph", "Gráfica de doble barra"), t("Scatter plot", "Gráfica de dispersión"), t("Circle graph", "Gráfica circular")]
    P = {0: t("Lines show how something changes over time.", "Las líneas muestran cómo cambia algo a lo largo del tiempo."), 1: t("Double bars compare two conditions in several categories.", "La doble barra compara dos condiciones en varias categorías."),
         2: t("A scatter plot looks for a relationship between two numbers measured on the same individuals.", "La dispersión busca relación entre dos números medidos en los mismos individuos."), 3: t("A circle graph shows the parts of one total (100%).", "La circular muestra las partes de un total (100 %).")}
    d = [
        (t("The percent of a city’s trash that is plastic, paper, food, and glass", "El porcentaje de la basura de una ciudad que es plástico, papel, comida y vidrio"), 3),
        (t("The height and the arm span of 30 students", "La estatura y la envergadura de los brazos de 30 estudiantes"), 2),
        (t("The populations of wolves and deer in a park, year by year, for 20 years", "Las poblaciones de lobos y de ciervos de un parque, año por año, durante 20 años"), 0),
        (t("Average yield of corn with and without fertilizer on four farms", "Rendimiento medio de maíz con y sin fertilizante en cuatro granjas"), 1),
        (t("The share of each gas in dry air: nitrogen, oxygen, argon, and others", "La proporción de cada gas en el aire seco: nitrógeno, oxígeno, argón y otros"), 3),
        (t("Monthly temperature in Chicago and in Miami during one year", "La temperatura mensual de Chicago y de Miami durante un año"), 0),
        (t("Hours of sleep and reaction time of 50 drivers", "Las horas de sueño y el tiempo de reacción de 50 conductores"), 2),
        (t("Number of seeds that sprouted with and without light, for three kinds of seeds", "Número de semillas germinadas con y sin luz, en tres tipos de semilla"), 1),
    ]
    return [{"enun": t("Which graph fits these data best?", "¿Qué gráfica corresponde mejor a estos datos?") + "<br><strong>" + x + "</strong>", "ops": T4, "ok": k, "enOrden": True,
             "pistas": {i: P[i] for i in range(4) if i != k}, "exp": f"<strong>{T4[k]}.</strong> " + P[k]} for x, k in d]


def banco_inter():
    O = [t("Interpolation: the data support it", "Interpolación: los datos la sostienen"), t("Extrapolation: it assumes the trend continues", "Extrapolación: supone que la tendencia continúa")]
    d = [
        (t("Plant height was measured at 10, 20, 30, and 40 days. Estimate the height at day 25.", "Se midió la altura de una planta a los 10, 20, 30 y 40 días. Estimar la altura a los 25 días."), 0, t("Day 25 is between days 20 and 30.", "El día 25 está entre los días 20 y 30.")),
        (t("Plant height was measured at 10, 20, 30, and 40 days. Estimate the height at day 60.", "Se midió la altura de una planta a los 10, 20, 30 y 40 días. Estimar la altura a los 60 días."), 1, t("Day 60 is beyond the last measurement (day 40).", "El día 60 está más allá de la última medición (día 40).")),
        (t("CO₂ data go from 1960 to 2020. Estimate the value in 1985.", "Los datos de CO₂ van de 1960 a 2020. Estimar el valor de 1985."), 0, t("1985 is inside the range 1960–2020.", "1985 está dentro del intervalo 1960–2020.")),
        (t("CO₂ data go from 1960 to 2020. Estimate the value in 2040.", "Los datos de CO₂ van de 1960 a 2020. Estimar el valor de 2040."), 1, t("2040 is after the last data point.", "2040 es posterior al último dato.")),
        (t("A gas was heated from 20 °C to 80 °C. Estimate its volume at −10 °C.", "Un gas se calentó de 20 °C a 80 °C. Estimar su volumen a −10 °C."), 1, t("−10 °C is below the lowest temperature measured.", "−10 °C está por debajo de la temperatura más baja medida.")),
        (t("Enzyme activity was measured at pH 2, 4, 6, and 8. Estimate the activity at pH 5.", "Se midió la actividad de una enzima a pH 2, 4, 6 y 8. Estimar la actividad a pH 5."), 0, t("pH 5 is between pH 4 and pH 6.", "pH 5 está entre pH 4 y pH 6.")),
        (t("A city’s population was counted every 10 years from 1950 to 2020. Estimate it in 2050.", "La población de una ciudad se contó cada 10 años de 1950 a 2020. Estimarla en 2050."), 1, t("2050 is outside the counted years.", "2050 queda fuera de los años contados.")),
        (t("A ball was dropped from 1, 2, 3, and 4 meters, and its bounce was measured. Estimate the bounce from 2.5 m.", "Una pelota se soltó desde 1, 2, 3 y 4 metros y se midió su rebote. Estimar el rebote desde 2.5 m."), 0, t("2.5 m is between 2 and 3 m.", "2.5 m está entre 2 y 3 m.")),
        (t("Seeds were tested at 10, 15, 20, and 25 °C. Estimate how many sprout at 30 °C.", "Se probaron semillas a 10, 15, 20 y 25 °C. Estimar cuántas germinan a 30 °C."), 1, t("30 °C is above the highest temperature tested, as the authors of the reading warned.", "30 °C está por encima de la temperatura más alta probada, como advirtieron los autores de la lectura.")),
        (t("Seeds were tested at 10, 15, 20, and 25 °C. Estimate how many sprout at 12 °C.", "Se probaron semillas a 10, 15, 20 y 25 °C. Estimar cuántas germinan a 12 °C."), 0, t("12 °C is between 10 and 15 °C.", "12 °C está entre 10 y 15 °C.")),
    ]
    return [{"enun": x, "ops": O, "ok": k, "enOrden": True, "exp": f"<strong>{O[k]}.</strong> {e}"} for x, k, e in d]


